function message(text,error=false){$('message').textContent=text;$('message').classList.toggle('error',error);}
function renderNote(target,notes,prefix='',empty=''){target.replaceChildren();const text=String(notes||'');if(!text){target.textContent=empty;return;}if(prefix)target.append(document.createTextNode(prefix));let start=0;for(const match of text.matchAll(/\b(?:not\s+sure|not\s+valid|invalid|valid)\b/gi)){target.append(document.createTextNode(text.slice(start,match.index)));const tag=document.createElement('span');tag.className='note-tag '+(/^not\s+sure$/i.test(match[0])?'note-unsure':/^(?:invalid|not\s+valid)$/i.test(match[0])?'note-invalid':'note-valid');tag.textContent=match[0];target.append(tag);start=match.index+match[0].length;}target.append(document.createTextNode(text.slice(start)));}
function editNotes(record,queueReview=false){if(!loadedContext||savingNotes)return;editing=record;reviewing=queueReview;$('save-next').hidden=!queueReview;$('invalid-reason').value=invalidReason(record.notes);$('history-list').replaceChildren();$('review-history').open=false;$('verdict-controls').hidden=String(record.status).toUpperCase()!=='XFER';$('review-audio').hidden=!queueReview;$('notes-customer').textContent=record.customer;$('notes-detail').textContent=`Lead ${record.lead} · ${record.time} · ${loadedContext.agent} · ${loadedContext.date}`;$('notes-text').value=record.notes||'';$('notes-status').textContent='';$('notes-status').className='';syncVerdict();if(!$('notes-dialog').open)$('notes-dialog').showModal();$('notes-text').focus();}
