async function saveNotes(advance=false){if(!editing||savingNotes||!authorization||!loadedContext)return;const record=editing,context={...loadedContext},notes=$('notes-text').value;const queue=advance?reviewCandidates():[];if(advance&&noteVerdict(notes)==='unreviewed'){$('notes-status').textContent='Choose Valid, Invalid or Not sure before continuing.';return;}if(notes===(record.notes||'')){if(advance){advanceReview(record,queue);return;}$('notes-status').textContent='No changes to save.';return;}let confirmed=false;savingNotes=true;saveBusy(true);$('notes-status').className='';$('notes-status').textContent='Saving notes…';try{const response=await fetch('/api/notes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({lead:record.lead,audio:record.audio,agent:context.agent,date:context.date,notes,previousNotes:record.notes||''})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Could not save notes.');if(!result.saved){$('notes-status').textContent=result.message||'The server did not confirm this save. Your draft is kept here.';return;}confirmed=true;noteRevision++;record.notes=notes;filter(false);if(playing===record)renderNote($('recording-notes'),notes,'Notes: ');$('notes-status').className='success';$('notes-status').textContent=result.historyWarning?'Notes saved. '+result.historyWarning:'Notes saved.';invalidateTeam();}catch(e){$('notes-status').className='error';$('notes-status').textContent=(e.message||'Could not confirm the save.')+' Your draft is kept here.';}finally{savingNotes=false;saveBusy(false);}if(advance&&confirmed)advanceReview(record,queue);}

