async function initializeLoginChallenge(){loginVerification.token='';updateLoginButton();$('retry-verification').hidden=true;try{
 const response=await fetch('/api/login-config');if(!response.ok)throw new Error();const config=await response.json();loginVerification.enabled=config.enabled!==false;
 if(!loginVerification.enabled){updateLoginButton();return;}
 if(!window.turnstile)await new Promise((resolve,reject)=>{const old=document.getElementById('turnstile-script');old?.remove();const script=document.createElement('script');script.id='turnstile-script';script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';script.async=true;const timer=setTimeout(()=>reject(new Error()),15000);script.onload=()=>{clearTimeout(timer);resolve();};script.onerror=()=>{clearTimeout(timer);reject(new Error());};document.head.append(script);});
 if(loginVerification.widget!==null)window.turnstile.remove(loginVerification.widget);
 loginVerification.widget=window.turnstile.render('#turnstile-widget',{sitekey:config.siteKey,action:'login',theme:'light',size:window.matchMedia?.('(max-width: 380px)').matches?'compact':'flexible',callback:token=>{loginVerification.token=token;updateLoginButton();},'expired-callback':()=>{loginVerification.token='';updateLoginButton();},'error-callback':()=>{loginVerification.token='';updateLoginButton();$('login-status').textContent='Security check failed. Retry the security check.';$('retry-verification').hidden=false;}});
 }catch{$('login-status').textContent='Could not load the security check. Please retry.';$('retry-verification').hidden=false;}}
