$('notes-form').onsubmit=e=>{e.preventDefault();saveNotes();};$('save-next').onclick=()=>saveNotes(true);$('notes-text').oninput=syncVerdict;for(const verdict of ['valid','invalid','unsure'])$('mark-'+verdict).onclick=()=>{const notes=setNoteVerdict($('notes-text').value,verdict);if(notes.length>4000){$('notes-status').textContent='Shorten this note to make room for the review label.';return;}$('notes-text').value=notes;syncVerdict();};$('review-queue').onchange=()=>{$('status-filter').value='';$('status-filter').disabled=$('review-queue').checked;filter();};$('review-next').onclick=()=>reviewCall(reviewCandidates()[0]);$('cancel-notes').onclick=closeNotes;$('notes-dialog').addEventListener('cancel',e=>{e.preventDefault();closeNotes();});$('edit-playing-notes').onclick=()=>{if(playing)editNotes(playing);};
