async function refreshRecordings(manual=false){
 if(reportPage||reportController||(!manual&&!autoRefresh)||refreshing||!authorization||!loadedContext||document.hidden||$('load').disabled)return;
 if(editing||savingNotes){if(manual)$('sync-status').textContent='Finish reviewing or saving this note before refreshing.';return;}
 const context=loadedContext,seq=loadSequence,revision=noteRevision;refreshing=true;$('refresh-now').disabled=true;$('refresh-now').textContent='Refreshing…';
 $('sync-status').textContent='Checking for new recordings…';
 try{
 const res=await fetch('/api/recordings?'+new URLSearchParams({u:context.agent,q:context.date}),{cache:'no-store',signal:AbortSignal.timeout(20000)});
 const data=await res.json();
 if(seq!==loadSequence||context!==loadedContext||!authorization)return;
 if(!res.ok)throw new Error(data.error||'Recording check failed.');
 if(editing||savingNotes||revision!==noteRevision){$('sync-status').textContent='Auto refresh paused during note review · Your draft is preserved';return;}
 if(!Array.isArray(data.recordings))throw new Error('Unexpected recording response.');
 const changed=JSON.stringify(recordings)!==JSON.stringify(data.recordings);
 if(changed){invalidateTeam();recordings=mergeRecordingRefresh(recordings,data.recordings);updateStatuses();filter(false);message(recordings.length.toLocaleString()+' recordings loaded. New recordings are checked automatically.');if(playing)renderNote($('recording-notes'),playing.notes,'Notes: ');}
 $('sync-status').textContent=(autoRefresh?'Auto refresh every '+refreshSeconds+' seconds':'Manual refresh')+' · Checked '+new Date().toLocaleTimeString()+ (changed?' · Recordings updated':'');
 if(agentsDate===context.date&&$('date').value===context.date){
 try{const response=await fetch('/api/agents?'+new URLSearchParams({date:context.date}),{cache:'no-store',signal:AbortSignal.timeout(20000)});const roster=await response.json();
 if(response.ok&&seq===loadSequence&&context===loadedContext&&$('date').value===context.date&&!$('agent-picker').disabled&&Array.isArray(roster.agents)){
 const selected=$('agent-picker').value;$('agent-picker').replaceChildren(new Option('Choose an agent…',''));
 for(const agent of roster.agents)$('agent-picker').add(new Option(agent.name,agent.username));$('agent-picker').value=selected;
 $('agents-message').textContent=roster.agents.length+' agents · '+context.date+' · Agent roster';
 }}catch{ /* Keep the last roster if the summary is temporarily unavailable. */ }
 }
 }catch(error){if(seq===loadSequence&&context===loadedContext&&authorization)$('sync-status').textContent='Auto refresh could not check · '+error.message+' Retrying in '+refreshSeconds+' seconds.';}
 finally{refreshing=false;$('refresh-now').disabled=false;$('refresh-now').textContent='Refresh now';}
}
function scheduleRefresh(){clearInterval(refreshTimer);if(autoRefresh)refreshTimer=setInterval(refreshRecordings,refreshSeconds*1000);}
scheduleRefresh();
$('refresh-interval').onchange=()=>{const seconds=Number($('refresh-interval').value);if(![30,60,120,300,600].includes(seconds))return;refreshSeconds=seconds;scheduleRefresh();$('sync-status').textContent=autoRefresh?'Auto refresh every '+refreshSeconds+' seconds':'Manual mode · Use Refresh now to check for recordings';};
$('auto-refresh').onclick=()=>{autoRefresh=!autoRefresh;scheduleRefresh();$('auto-refresh').setAttribute('aria-checked',String(autoRefresh));$('auto-refresh').textContent=autoRefresh?'Auto':'Manual';$('sync-status').textContent=autoRefresh?'Auto refresh every '+refreshSeconds+' seconds':'Manual mode · Use Refresh now to check for recordings';};
