let teamData=null,teamVersion=0,reportController=null,reportBlobUrl='';
function resetReports(){reportController?.abort();if(reportBlobUrl)URL.revokeObjectURL(reportBlobUrl);reportBlobUrl='';$('report-preview').hidden=true;$('report-text').textContent='';$('report-status').textContent='';invalidateTeam();}
function invalidateTeam(){teamVersion++;teamData=null;$('team-results').hidden=true;}
$('invalid-reason').onchange=()=>{const notes=setInvalidReason($('notes-text').value,$('invalid-reason').value);if(notes.length>4000){$('notes-status').textContent='Shorten the note to add this reason.';return;}$('notes-text').value=notes;syncVerdict();};
$('playback-speed').onchange=()=>{$('player').playbackRate=Number($('playback-speed').value);rememberPreferences();};
function skipAudio(seconds){const player=$('player');if(!Number.isFinite(player.duration))return;player.currentTime=Math.min(player.duration,Math.max(0,player.currentTime+seconds));}
$('skip-back').onclick=()=>skipAudio(-10);$('skip-forward').onclick=()=>skipAudio(10);
function rememberPreferences(){try{localStorage.setItem('qa-preferences',JSON.stringify({autoRefresh,refreshSeconds,status:$('status-filter').value,sort:$('time-sort').value,search:$('search').value,queue:$('review-queue').checked,further:$('further-review').checked,speed:$('playback-speed').value}));}catch{}}
function restorePreferences(){try{const p=JSON.parse(localStorage.getItem('qa-preferences')||'null');if(!p||typeof p!=='object')return;if(typeof p.autoRefresh==='boolean')autoRefresh=p.autoRefresh;if([30,60,120,300,600].includes(p.refreshSeconds))refreshSeconds=p.refreshSeconds;$('refresh-interval').value=String(refreshSeconds);$('auto-refresh').setAttribute('aria-checked',String(autoRefresh));$('auto-refresh').textContent=autoRefresh?'Auto':'Manual';if(['original','earliest','latest'].includes(p.sort))$('time-sort').value=p.sort;if(typeof p.search==='string')$('search').value=p.search.slice(0,200);$('review-queue').checked=p.queue===true;$('further-review').checked=!$('review-queue').checked&&p.further===true;if(['0.75','1','1.25','1.5','2'].includes(p.speed))$('playback-speed').value=p.speed;pendingStatus=typeof p.status==='string'?p.status:'';scheduleRefresh();}catch{}}
let pendingStatus='';restorePreferences();
for(const id of ['refresh-interval','auto-refresh','status-filter','time-sort','search','review-queue','further-review'])$(id).addEventListener(id==='search'?'input':id==='auto-refresh'?'click':'change',rememberPreferences);
async function collectTeam(date,signal,selectedAgents=null){const version=teamVersion;let roster;if(selectedAgents)roster={agents:selectedAgents};else{const response=await fetch('/api/agents?'+new URLSearchParams({date}),{signal});roster=await response.json();if(!response.ok)throw new Error(roster.error||'Could not load agents.');}const report=[];for(const [index,agent] of roster.agents.entries()){$('report-status').textContent='Loading '+(index+1)+' of '+roster.agents.length+' agents: '+agent.name;const response=await fetch('/api/recordings?'+new URLSearchParams({u:agent.username,q:date}),{signal});const data=await response.json();if(!response.ok||!Array.isArray(data.recordings))throw new Error('Could not load '+agent.name+'. '+(data.error||'No report was downloaded.'));report.push({...agent,recordings:data.recordings});}if(version===teamVersion)teamData={date,agents:report};return report;}
function showTeamProgress(agents){const host=$('team-results');host.replaceChildren();const table=document.createElement('table');const header=document.createElement('tr');for(const text of ['Agent','Transfers','Valid','Invalid','Not sure','Unreviewed','Reviewed']){const th=document.createElement('th');th.textContent=text;header.append(th);}table.append(header);for(const agent of agents){const counts=transferCounts(agent.recordings),row=document.createElement('tr');for(const value of [agent.name,counts.total,counts.valid,counts.invalid,counts.unsure,counts.unreviewed,counts.total?Math.round((counts.valid+counts.invalid)/counts.total*100)+'%':'—']){const cell=document.createElement('td');cell.textContent=value;row.append(cell);}table.append(row);}host.append(table);host.hidden=false;}
async function reportAction(progressOnly=false){if(reportController)return;if(editing||savingNotes){$('report-status').textContent='Finish reviewing this note before generating a report.';return;}if(!$('report-date').reportValidity())return;const date=$('report-date').value;const selected=selectedReportAgents();if(!selected.length||reportRosterDate!==date){$('report-status').textContent='Load agents for this date and select at least one agent.';return;}const context={date,agent:selected[0].username};const all=selected.length>1,format=$('report-format').value,scope=$('report-valid').checked?'followup-valid':'followup';if(!progressOnly){if(reportBlobUrl)URL.revokeObjectURL(reportBlobUrl);reportBlobUrl='';$('report-preview').hidden=true;$('report-text').textContent='';}const controller=new AbortController();reportController=controller;$('cancel-report').hidden=false;for(const id of ['export-report','team-progress'])$(id).disabled=true;try{const agents=await collectTeam(context.date,controller.signal,selected);if(controller.signal.aborted)return;if(progressOnly){showTeamProgress(agents);$('report-status').textContent=agents.length+' agents · '+context.date+' · Counts from actual recording lists · Not sure remains pending';}else{const text=reviewReport(agents,context.date,format,scope);if(reportBlobUrl)URL.revokeObjectURL(reportBlobUrl);reportBlobUrl=URL.createObjectURL(new Blob([text],{type:format==='csv'?'text/csv;charset=utf-8':'text/plain;charset=utf-8'}));const link=$('report-download');link.href=reportBlobUrl;link.download='qa-'+(all?'selected-agents':context.agent)+'-'+context.date+'.'+format;$('report-text').textContent=text;$('report-preview').hidden=false;$('report-preview').open=true;link.click();$('report-status').textContent='Report ready · '+agents.length+' agents · '+context.date;}}catch(error){$('report-status').textContent=error.name==='AbortError'?'Report cancelled.':error.message;}finally{reportController=null;$('cancel-report').hidden=true;for(const id of ['export-report','team-progress'])$(id).disabled=false;}}
$('export-report').onclick=()=>reportAction(false);$('team-progress').onclick=()=>reportAction(true);$('cancel-report').onclick=()=>reportController?.abort();
$('load-history').onclick=async()=>{if(!editing||!loadedContext)return;const record=editing,context=loadedContext;const host=$('history-list');host.textContent='Loading history…';try{const response=await fetch('/api/history?'+new URLSearchParams({lead:record.lead,audio:record.audio,agent:context.agent,date:context.date}));const data=await response.json();if(editing!==record)return;if(!response.ok)throw new Error(data.error||'History unavailable.');host.replaceChildren();if(!data.events.length)host.textContent='No changes recorded by this app yet.';for(const event of data.events){const item=document.createElement('div');item.className='history-event';const heading=document.createElement('strong');heading.textContent=event.reviewer+' · '+new Date(event.timestamp).toLocaleString();const before=document.createElement('pre');before.textContent=(event.previousNotesSource==='viewer'?'Before (loaded in viewer): ':'Before: ')+(event.previousNotes===null?'Unavailable':event.previousNotes||'—');const after=document.createElement('pre');after.textContent='After: '+event.notes;item.append(heading,before,after);host.append(item);}}catch(error){if(editing===record)host.textContent=error.message;}};

let reportRoster=[],reportRosterDate='',reportRosterSequence=0,reportRosterRequest=null;
$('report-date').value=$('date').value;
const viewerBase=location.pathname.replace(/\/(?:reports|activity|live|team)\/?$/,'').replace(/\/?$/,'/');
const viewerQuery=new URLSearchParams({u:$('agent').value,q:$('date').value});$('open-reports').href=viewerBase+'reports?'+viewerQuery;$('back-recordings').href=viewerBase+'?'+viewerQuery;
function selectedReportAgents(){const usernames=new Set([...$('report-agent-list').querySelectorAll('input:checked')].map(input=>input.value));return reportRoster.filter(agent=>usernames.has(agent.username));}
async function loadReportRoster(){if(!authorization||!$('report-date').reportValidity())return;resetReports();reportRosterRequest?.abort();const controller=new AbortController();reportRosterRequest=controller;const seq=++reportRosterSequence;const date=$('report-date').value;reportRosterDate='';reportRoster=[];$('report-agent-list').replaceChildren();$('report-roster-status').textContent='Loading agents…';$('load-report-agents').disabled=true;try{const response=await fetch('/api/agents?'+new URLSearchParams({date}),{signal:controller.signal});const data=await response.json();if(seq!==reportRosterSequence)return;if(!response.ok)throw new Error(data.error||'Could not load agents.');reportRoster=data.agents;reportRosterDate=date;for(const agent of reportRoster){const row=document.createElement('div');row.className='report-agent';const label=document.createElement('label');label.className='queue-toggle';const input=document.createElement('input');input.type='checkbox';input.value=agent.username;input.checked=agent.username===$('agent').value;label.append(input,document.createTextNode(agent.name));const button=document.createElement('button');button.type='button';button.textContent='Generate individually';button.setAttribute('aria-label','Generate report for '+agent.name);button.onclick=()=>{if(reportController)return;for(const checkbox of $('report-agent-list').querySelectorAll('input'))checkbox.checked=checkbox.value===agent.username;reportAction(false);};row.append(label,button);$('report-agent-list').append(row);}$('report-roster-status').textContent=data.agents.length+' agents · '+date+' · Select agents for a combined report, or generate individually';}catch(error){if(seq===reportRosterSequence&&error.name!=='AbortError')$('report-roster-status').textContent=error.message;}finally{if(seq===reportRosterSequence)$('load-report-agents').disabled=false;}}
$('load-report-agents').onclick=loadReportRoster;$('report-date').onchange=loadReportRoster;
$('select-all-agents').onclick=()=>{for(const input of $('report-agent-list').querySelectorAll('input'))input.checked=true;};$('clear-report-agents').onclick=()=>{for(const input of $('report-agent-list').querySelectorAll('input'))input.checked=false;};

const ACTIVITY_PAUSE_LABELS={'1':'Break','2':'Closer Transfer','3':'Training','4':'Restroom','5':'Call Back','6':'Lunch'};const ACTIVITY_STATUS_LABELS={A:'Answering Machine',TB:'Toss Back',NI:'Not Interested',NQI:'Wrong Info',AGE:'Too Old',XFAIL:'Transfer Failed',CANHRT:'Cancer Heart Disease',DNC:'DO NOT CALL',FINDSC:'Financial Decision'};
let activityRequest=null,activitySequence=0,cutoffData=null;
$('activity-agent').value=$('agent').value;$('activity-date').value=$('date').value;$('activity-end').value=$('date').value;$('pay-date').value=$('date').value;restorePayroll();
$('open-activity').href=viewerBase+'activity?'+viewerQuery;$('activity-back').href=viewerBase+'?'+viewerQuery;
function hours(seconds){if(seconds===null||seconds===undefined)return 'Unavailable';const n=Math.round(seconds);return Math.floor(n/3600)+':'+String(Math.floor(n%3600/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');}
async function loadActivityAgents(){try{const response=await fetch('/api/agents?'+new URLSearchParams({date:$('activity-date').value}));const data=await response.json();if(!response.ok)throw new Error(data.error);if(!authorization)return;$('activity-picker').replaceChildren(new Option('Choose an agent',''),...data.agents.map(a=>new Option(a.name,a.username)));$('activity-picker').value=$('activity-agent').value;}catch(error){$('activity-message').textContent=error.message||'Could not load agents.';}}
$('activity-picker').onchange=()=>{activitySequence++;activityRequest?.abort();$('activity-results').hidden=true;if($('activity-picker').value)$('activity-agent').value=$('activity-picker').value;restorePayroll();};
$('activity-end').onchange=()=>{activitySequence++;activityRequest?.abort();$('activity-results').hidden=true;};
$('activity-date').onchange=()=>{activitySequence++;activityRequest?.abort();$('activity-results').hidden=true;loadActivityAgents();};
$('activity-agent').oninput=()=>{restorePayroll();activitySequence++;activityRequest?.abort();$('activity-results').hidden=true;};
$('activity-form').onsubmit=async e=>{e.preventDefault();$('activity-results').classList.remove('saved-snapshot');activityRequest?.abort();const controller=new AbortController();activityRequest=controller;const seq=++activitySequence;const agent=$('activity-agent').value,date=$('activity-date').value,end=$('activity-end').value;$('activity-load').disabled=true;$('activity-results').hidden=true;$('activity-message').textContent='Loading activity…';try{const dates=cutoffDates(date,end);const days=[];cutoffData=null;for(const day of dates){$('activity-message').textContent='Loading '+day+' · '+(days.length+1)+' of '+dates.length;const response=await fetch('/api/activity?'+new URLSearchParams({u:agent,q:day}),{signal:controller.signal});const result=await response.json();if(!response.ok)throw new Error(day+': '+(result.error||'Could not load activity.'));if(result.rows===0&&result.calls===0)result.totals={talk:0,wait:0,dispo:0,pause:0,dead:0};days.push({...result,date:day});}const data=mergeCutoff(days);cutoffData={agent,name:$('activity-picker').value===agent?($('activity-picker').selectedOptions[0]?.textContent||agent):agent,start:date,end,days,data};renderBreakAdjustments();renderPayslip();if(seq!==activitySequence||!authorization)return;renderActivityMetrics(data);function rows(id,values){const host=$(id);host.replaceChildren();for(const valuesRow of values){const tr=document.createElement('tr');for(const value of valuesRow){const td=document.createElement('td');td.textContent=value;tr.append(td);}host.append(tr);}}rows('activity-pauses',data.pauses.map(p=>[p.campaign,p.code,p.campaign==='INS'?(ACTIVITY_PAUSE_LABELS[p.code]||p.code):p.code,hours(p.seconds),p.entries]));rows('activity-statuses',data.statuses.map(s=>[s.status,ACTIVITY_STATUS_LABELS[s.status]||s.status,s.calls,hours(s.seconds)]));$('activity-results').hidden=false;$('activity-message').textContent=agent+' · '+date+' to '+end+' · '+data.rows+' activity entries'+(data.truncated?' · ViciDial row limit reached; activity totals may be incomplete.':data.rows?'':' · No activity entries available.');}catch(error){if(error.name!=='AbortError'&&seq===activitySequence)$('activity-message').textContent=error.message||'Could not load activity.';}finally{if(activityRequest===controller){activityRequest=null;$('activity-load').disabled=false;}}};

function cutoffDates(start,end){if(!/^\d{4}-\d{2}-\d{2}$/.test(start)||!/^\d{4}-\d{2}-\d{2}$/.test(end))throw new Error('Choose valid cutoff dates.');const first=Date.parse(start+'T00:00:00Z'),last=Date.parse(end+'T00:00:00Z');if(!Number.isFinite(first)||!Number.isFinite(last)||new Date(first).toISOString().slice(0,10)!==start||new Date(last).toISOString().slice(0,10)!==end||last<first)throw new Error('Cutoff end must be on or after the start.');if((last-first)/86400000>=31)throw new Error('Select a cutoff of up to 31 days.');return Array.from({length:(last-first)/86400000+1},(_,n)=>new Date(first+n*86400000).toISOString().slice(0,10));}
function mergeCutoff(days){const result={calls:0,callSeconds:0,sessionSeconds:0,rows:0,truncated:false,totals:{talk:0,wait:0,dispo:0,pause:0,dead:0},pauses:[],statuses:[]};const pauses=new Map(),statuses=new Map();for(const day of days){for(const key of ['calls','callSeconds','sessionSeconds'])result[key]=result[key]===null||day[key]===null?null:result[key]+day[key];result.rows+=day.rows;result.truncated ||= day.truncated;if(!day.totals)result.totals=null;else if(result.totals)for(const key of Object.keys(result.totals))result.totals[key]+=day.totals[key];for(const p of day.pauses){const key=p.campaign+'|'+p.code,old=pauses.get(key)||{...p,seconds:0,entries:0};old.seconds+=p.seconds;old.entries+=p.entries;pauses.set(key,old);}for(const s of day.statuses){const old=statuses.get(s.status)||{...s,calls:0,seconds:0};old.calls+=s.calls;old.seconds=old.seconds===null||s.seconds===null?null:old.seconds+s.seconds;statuses.set(s.status,old);}}result.pauses=[...pauses.values()].sort((a,b)=>b.seconds-a.seconds);result.statuses=[...statuses.values()];return result;}
function payrollAmounts(days,rate,lunchMinutes=0,adjustments={},rule={}){if(!Number.isFinite(lunchMinutes)||lunchMinutes<0||lunchMinutes>240)throw new Error('Lunch minimum must be between 0 and 240 minutes.');if(!Number.isFinite(rate)||rate<0||rate>100000)throw new Error('Enter a valid hourly rate.');if(days.some(d=>!d.totals||d.truncated))throw new Error('Payslip unavailable: activity data is missing or incomplete.');const rows=days.map(d=>{const baseSeconds=(rule.talk===false?0:d.totals.talk)+(rule.wait===false?0:d.totals.wait)+(rule.dispo===false?0:d.totals.dispo);const recordedLunch=d.pauses.filter(p=>p.campaign==='INS'&&p.code==='6').reduce((sum,p)=>sum+p.seconds,0);const lunch=baseSeconds>0||recordedLunch>0?Math.max(recordedLunch,lunchMinutes*60):recordedLunch;const deduction=rule.lunch===false?0:Math.min(baseSeconds,Math.max(0,lunch-recordedLunch));const correction=adjustments[d.date]||{},minutes=Number(correction.minutes||0);if(!Number.isFinite(minutes)||minutes<0||minutes>1440)throw new Error(d.date+': enter 0–1,440 unpaid break minutes.');const manualDeduction=rule.manual===false?0:Math.round(minutes*60);if(manualDeduction>baseSeconds-deduction)throw new Error(d.date+': unpaid break exceeds remaining billable hours.');const seconds=baseSeconds-deduction-manualDeduction;return {seconds,manualDeduction,baseSeconds,recordedLunch,lunch,deduction,cents:Math.round(seconds*rate/3600*100)};});return {rows,seconds:rows.reduce((n,r)=>n+r.seconds,0),cents:rows.reduce((n,r)=>n+r.cents,0)};}
function restorePayroll(){try{const config=JSON.parse(localStorage.getItem('qa-payroll')||'{}');$('pay-lunch').value=config.lunchMinutes??60;setPayrollRule(config.rule);$('pay-company').value=config.company||'AIG';$('pay-currency').value=config.currencies?.[$('activity-agent').value]||'USD';$('pay-rate').value=config.rates?.[$('activity-agent').value]??'';}catch{}}
function rememberPayroll(){try{const config=JSON.parse(localStorage.getItem('qa-payroll')||'{}');config.rule=getPayrollRule();config.lunchMinutes=Number($('pay-lunch').value);config.company=$('pay-company').value;config.currencies ||= {};config.currencies[$('activity-agent').value]=$('pay-currency').value;config.rates ||= {};if($('pay-rate').value!=='')config.rates[$('activity-agent').value]=$('pay-rate').value;localStorage.setItem('qa-payroll',JSON.stringify(config));}catch{}}
function renderPayslip(){if(!cutoffData)return;const c=cutoffData;const rate=Number($('pay-rate').value),currency=$('pay-currency').value;const money=cents=>new Intl.NumberFormat('en-US',{style:'currency',currency}).format(cents/100);$('pay-print').disabled=true;$('pay-save').disabled=true;$('slip-company').textContent=$('pay-company').value||'Company';$('slip-details').textContent=(c.name==='Choose an agent'?c.agent:c.name)+' ('+c.agent+') · '+c.start+' to '+c.end+' · Payment date: '+($('pay-date').value||'Not set');$('slip-notes').textContent=$('pay-notes').value+Object.entries(c.adjustments||{}).filter(([,v])=>Number(v.minutes)>0).map(([date,v])=>'\n'+date+': additional unpaid break '+v.minutes+' minutes'+(v.reason?' · '+v.reason:'')).join('');$('slip-days').replaceChildren();$('slip-total').replaceChildren();$('slip-summary').replaceChildren();try{if($('pay-rate').value==='')throw new Error('Enter this agent’s hourly rate to generate compensation.');const pay=payrollAmounts(c.days,rate,Number($('pay-lunch').value),c.adjustments||{},getPayrollRule());const table=$('slip-days');for(let n=0;n<c.days.length;n++){const day=c.days[n],r=pay.rows[n],tr=document.createElement('tr');const pause=code=>day.pauses.filter(p=>p.campaign==='INS'&&p.code===code).reduce((total,p)=>total+p.seconds,0);for(const value of [day.date,day.calls??'Unavailable',hours(day.totals.talk),hours(day.totals.wait),hours(day.totals.dispo),hours(day.totals.pause),hours(pause('1')),hours(pause('2')),hours(pause('3')),hours(pause('4')),hours(pause('5')),hours(r.recordedLunch),hours(r.lunch),hours(r.deduction),hours(r.manualDeduction),hours(r.seconds)+' ('+(r.seconds/3600).toFixed(4)+')',money(Math.round(rate*100)),money(r.cents)]){const td=document.createElement('td');td.textContent=value;tr.append(td);}table.append(tr);}const total=document.createElement('tr'),label=document.createElement('th'),amount=document.createElement('th');label.colSpan=17;label.textContent='Total billable: '+hours(pay.seconds)+' · Total compensation';amount.textContent=money(pay.cents);total.append(label,amount);$('slip-total').append(total);for(const [label,value] of [['Adjusted billable hours',hours(pay.seconds)],['Lunch shortfall deducted',hours(pay.rows.reduce((sum,r)=>sum+r.deduction,0))],['Additional unpaid break',hours(pay.rows.reduce((sum,r)=>sum+r.manualDeduction,0))],['Hourly rate',money(Math.round(rate*100))],['Total compensation',money(pay.cents)]]){const card=document.createElement('div'),name=document.createElement('span'),strong=document.createElement('strong');name.textContent=label;strong.textContent=value;card.append(name,strong);$('slip-summary').append(card);}$('pay-message').textContent='Payslip ready. Payroll rules are remembered in this browser and included in saved payslips.';$('slip-rule').textContent=payrollRuleDescription();$('pay-print').disabled=false;$('pay-save').disabled=false;renderActivityMetrics(c.data);applyPayslipColumns();}catch(error){$('pay-message').textContent=error.message;}}
for(const id of ['pay-company','pay-rate','pay-currency','pay-date','pay-notes','pay-lunch'])$(id).oninput=()=>{rememberPayroll();renderPayslip();};
$('pay-print').onclick=()=>{if(!cutoffData||$('pay-print').disabled)return;document.body.classList.add('printing-payslip');window.print();};window.addEventListener('afterprint',()=>document.body.classList.remove('printing-payslip'));

$('pay-save').onclick=async()=>{if(!cutoffData||$('pay-save').disabled)return;const snapshot={cutoff:cutoffData,company:$('pay-company').value,rate:$('pay-rate').value,currency:$('pay-currency').value,paymentDate:$('pay-date').value,notes:$('pay-notes').value,lunchMinutes:Number($('pay-lunch').value),rule:getPayrollRule()};$('pay-save').disabled=true;try{const response=await fetch('/api/payslips',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(snapshot)});const data=await response.json();if(!response.ok)throw new Error(data.error);$('pay-message').textContent='Payslip saved. Reopen it from Saved payslips without loading activity again.';loadSavedPayslips();}catch(error){$('pay-message').textContent=error.message;}finally{$('pay-save').disabled=false;}};
async function loadSavedPayslips(){const host=$('saved-list');$('saved-message').textContent='Loading saved payslips…';try{const response=await fetch('/api/payslips');const data=await response.json();if(!response.ok)throw new Error(data.error);if(!authorization)return;host.replaceChildren();for(const entry of data.entries){const row=document.createElement('div'),name=document.createElement('span'),load=document.createElement('button'),remove=document.createElement('button');row.className='saved-payslip-row';name.textContent=entry.name+' · '+entry.start+' to '+entry.end+' · '+entry.currency;load.textContent='Load';remove.textContent='Delete';load.onclick=async()=>{try{const response=await fetch('/api/payslips?id='+entry.id),data=await response.json();if(!response.ok)throw new Error(data.error);if(!authorization)return;const s=data.snapshot;setPayrollRule(s.rule);activitySequence++;activityRequest?.abort();cutoffData=s.cutoff;$('activity-agent').value=cutoffData.agent;$('activity-date').value=cutoffData.start;$('activity-end').value=cutoffData.end;for(const [id,value] of [['pay-company',s.company],['pay-rate',s.rate],['pay-currency',s.currency],['pay-date',s.paymentDate],['pay-notes',s.notes],['pay-lunch',s.lunchMinutes??0]])$(id).value=value??'';renderBreakAdjustments();renderPayslip();$('activity-results').classList.add('saved-snapshot');$('activity-results').hidden=false;$('activity-metrics').replaceChildren();$('activity-pauses').replaceChildren();$('activity-statuses').replaceChildren();$('activity-message').textContent='Saved payslip snapshot · '+cutoffData.start+' to '+cutoffData.end+' · Activity was not refetched.';}catch(error){$('saved-message').textContent=error.message;}};remove.onclick=async()=>{if(!confirm('Delete this saved payslip from the list?'))return;try{const response=await fetch('/api/payslips?id='+entry.id,{method:'DELETE'});if(!response.ok)throw new Error((await response.json()).error);loadSavedPayslips();}catch(error){$('saved-message').textContent=error.message;}};row.append(name,load,remove);host.append(row);}$('saved-message').textContent=data.entries.length+' saved payslips';}catch(error){$('saved-message').textContent=error.message;}}
$('load-saved-payslips').onclick=loadSavedPayslips;

function renderBreakAdjustments(){const host=$('break-adjustments');host.replaceChildren();if(!cutoffData)return;cutoffData.adjustments ||= {};for(const day of cutoffData.days){const row=document.createElement('div'),label=document.createElement('label'),input=document.createElement('input'),reason=document.createElement('input');row.className='break-adjustment-row';label.textContent=day.date+' · Additional unpaid break (minutes)';input.type='number';input.min='0';input.max='1440';input.step='1';input.value=cutoffData.adjustments[day.date]?.minutes||0;input.setAttribute('aria-label',day.date+' unpaid break minutes');reason.maxLength=200;reason.placeholder='Reason, e.g. forgot to log out';reason.setAttribute('aria-label',day.date+' adjustment reason');reason.value=cutoffData.adjustments[day.date]?.reason||'';const update=()=>{cutoffData.adjustments[day.date]={minutes:input.value,reason:reason.value};renderPayslip();};input.oninput=update;reason.oninput=update;label.append(input);row.append(label,reason);host.append(row);}}

function renderActivityMetrics(data){
 if(!data)return;const host=$('activity-metrics');host.replaceChildren();
 const t=data.totals;let billable=t?hours(t.talk+t.wait+t.dispo):'Unavailable';
 try{if(cutoffData)billable=hours(payrollAmounts(cutoffData.days,0,Number($('pay-lunch').value),cutoffData.adjustments||{},getPayrollRule()).seconds);}catch{billable='Unavailable';}
 const pause=code=>t?hours(data.pauses.filter(p=>p.campaign==='INS'&&p.code===code).reduce((n,p)=>n+p.seconds,0)):'Unavailable';
 const groups=[['Totals','overview',[['Total calls',data.calls??'Unavailable'],['Total login sessions',hours(data.sessionSeconds)],['Total billable hours',billable]]],['Billable','billable',[['Activity talk',hours(t?.talk)],['Waiting',hours(t?.wait)],['Wrap-up',hours(t?.dispo)]]],['Non-billable','nonbillable',[['All pauses',hours(t?.pause)],['Break',pause('1')],['Restroom',pause('4')],['Recorded lunch',pause('6')]]],['Reference totals','reference',[['Call time',hours(data.callSeconds)],['Dead time',hours(t?.dead)]]]];
 const rule=getPayrollRule();const timed=[['talk','Activity talk'],['wait','Waiting'],['dispo','Wrap-up']];groups[1][2]=timed.filter(([k])=>rule[k]).map(([k,label])=>[label,hours(t?.[k])]);groups[2][2].push(...timed.filter(([k])=>!rule[k]).map(([k,label])=>[label+' (excluded)',hours(t?.[k])]));for(const [title,theme,values]of groups){const section=document.createElement('section');section.className='activity-metric-group '+theme;const heading=document.createElement('h3');heading.textContent=title;const grid=document.createElement('div');grid.className='activity-metrics';for(const[label,value]of values){const card=document.createElement('div'),name=document.createElement('span'),number=document.createElement('strong');name.textContent=label;number.textContent=value;card.append(name,number);grid.append(card);}section.append(heading,grid);host.append(section);}
}

const PAYSLIP_COLUMNS=['Day','Calls','Talk','Wait','Wrap-up','Pauses','Recorded break','Transfer','Training','Restroom','Call Back','Recorded lunch','Payroll lunch','Lunch deduction','Additional unpaid break','Billable hours','Rate / hour','Compensation'];
const PAYSLIP_OPTIONAL=new Set([6,7,10,12,14]);
let payslipColumnOverrides={};
function applyPayslipColumns(){
 const table=$('payslip').querySelector('table'),rows=[...$('slip-days').rows],compact=$('pay-view').value==='professional';
 table.classList.toggle('professional-table',compact);let visible=0;
 PAYSLIP_COLUMNS.forEach((name,i)=>{const zero=i>1&&i<15&&rows.length>0&&rows.every(row=>/^0:00:00$/.test(row.cells[i]?.textContent||''));const show=payslipColumnOverrides[i]??((!compact||!PAYSLIP_OPTIONAL.has(i))&&(!$('pay-hide-zero').checked||!zero));for(const row of [table.tHead.rows[0],...rows])if(row.cells[i])row.cells[i].hidden=!show;if(show)visible++;const input=$('pay-columns').querySelector('[data-column="'+i+'"]');if(input)input.checked=show;});
 if($('slip-total').rows[0])$('slip-total').rows[0].cells[0].colSpan=Math.max(1,visible-1);
}
for(let i=0;i<PAYSLIP_COLUMNS.length;i++){const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.dataset.column=i;input.disabled=[0,15,17].includes(i);input.onchange=()=>{payslipColumnOverrides[i]=input.checked;applyPayslipColumns();};label.append(input,document.createTextNode(PAYSLIP_COLUMNS[i]));$('pay-columns').append(label);}
$('pay-view').onchange=()=>{payslipColumnOverrides={};$('pay-hide-zero').checked=$('pay-view').value==='professional';applyPayslipColumns();};
$('pay-hide-zero').onchange=()=>{payslipColumnOverrides={};applyPayslipColumns();};

function getPayrollRule(){return Object.fromEntries(['talk','wait','dispo','lunch','manual'].map(k=>[k,$('rule-'+k).checked]));}
function setPayrollRule(rule={}){for(const k of ['talk','wait','dispo','lunch','manual'])$('rule-'+k).checked=rule?.[k]!==false;}
function payrollRuleDescription(){const r=getPayrollRule();return 'Paid time: '+[['talk','Talk'],['wait','Waiting'],['dispo','Wrap-up']].filter(([k])=>r[k]).map(([,v])=>v).join(' + ')+'. Deductions: '+([r.lunch?'Lunch shortfall':null,r.manual?'Additional unpaid break':null].filter(Boolean).join(' + ')||'None')+'. Recorded pauses remain excluded. Daily compensation rounds to two decimals.';}
for(const k of ['talk','wait','dispo','lunch','manual'])$('rule-'+k).onchange=()=>{rememberPayroll();renderPayslip();};

$('copy-recording').onclick=async()=>{const url=playing?recordingLink(playing):'';const status=$('copy-recording-status');if(!url){status.textContent='Recording address unavailable.';return;}try{await navigator.clipboard.writeText(url);status.textContent='Address copied';}catch{status.replaceChildren(document.createTextNode('Copy this address: '));const input=document.createElement('input');input.value=url;input.readOnly=true;input.setAttribute('aria-label','Recording address');status.append(input);input.select();}};

$('open-live').href=viewerBase+'live';$('live-back').href=viewerBase;
let liveTimer=null,liveRequest=null,liveUsername='',liveBusy=false,liveGeneration=0;
function stopLive(){clearTimeout(liveTimer);liveTimer=null;liveGeneration++;liveRequest?.abort();}
async function startLive(){const response=await fetch('/api/session');if(!response.ok||!authorization)return;const data=await response.json();liveUsername=data.username;try{$('live-phone').value=localStorage.getItem('qa-live-phone:'+liveUsername)||'';}catch{}loadLive();}
function scheduleLive(){clearTimeout(liveTimer);const seconds=Number($('live-interval').value);if(livePage&&authorization&&seconds>0)liveTimer=setTimeout(()=>{if(document.hidden)scheduleLive();else loadLive();},seconds*1000);}
async function loadLive(){if(!authorization||liveRequest||liveBusy)return;clearTimeout(liveTimer);const controller=new AbortController(),generation=liveGeneration;liveRequest=controller;$('live-refresh').disabled=true;try{const response=await fetch('/api/live?'+new URLSearchParams({phone:$('live-phone').value.trim()}),{signal:controller.signal});const data=await readLiveResponse(response);if(!response.ok)throw Error(data.error);if(generation!==liveGeneration||!authorization)return;const host=$('live-rows');host.replaceChildren();for(const agent of data.agents){const row=document.createElement('tr');for(const value of [agent.name,agent.station,agent.campaign,agent.status,agent.pause||'—',agent.time,agent.calls,agent.customer||'—',(agent.monitorRequests||[]).map(r=>r.supervisor+' · '+(r.mode==='WHISPER'?'Whisper':'Listen')+' · Ext '+r.phone+' · '+new Date(r.acceptedAt).toLocaleString()).join('\n')||'—']){const cell=document.createElement('td');cell.textContent=value;row.append(cell);}const actions=document.createElement('td');for(const [mode,label]of [['MONITOR','Listen'],['WHISPER','Whisper']]){const button=document.createElement('button');button.type='button';button.textContent=label;button.setAttribute('aria-label',label+' to '+agent.name);button.onclick=()=>monitorAgent(agent,mode);actions.append(button);}row.append(actions);host.append(row);}$('live-status').textContent=data.agents.length+' live agents · Updated '+new Date(data.updatedAt).toLocaleTimeString();}catch(error){if(error.name!=='AbortError')$('live-status').textContent=error.message+' Last successful list retained.';}finally{if(liveRequest===controller)liveRequest=null;$('live-refresh').disabled=false;scheduleLive();}}
async function monitorAgent(agent,mode){if(liveBusy||!authorization)return;const phone=$('live-phone').value.trim();if(!/^\d{1,20}$/.test(phone)){$('live-command-status').textContent='Enter your assigned supervisor extension first.';$('live-phone').focus();return;}const commandGeneration=liveGeneration;liveBusy=true;liveRequest?.abort();clearTimeout(liveTimer);for(const button of $('live-rows').querySelectorAll('button'))button.disabled=true;$('live-command-status').textContent='Requesting '+(mode==='WHISPER'?'Whisper':'Listen')+' for '+agent.name+'…';try{const response=await fetch('/api/monitor',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({session:agent.session,phone,mode})});const data=await readLiveResponse(response);if(!response.ok)throw Error(data.error);if(authorization&&commandGeneration===liveGeneration)$('live-command-status').textContent=data.message;}catch(error){if(authorization&&commandGeneration===liveGeneration)$('live-command-status').textContent=error.message||'Monitoring was not confirmed. Check your phone before trying again.';}finally{liveBusy=false;for(const button of $('live-rows').querySelectorAll('button'))button.disabled=false;if(authorization&&commandGeneration===liveGeneration)loadLive();else scheduleLive();}}
$('live-phone').onchange=()=>{try{if(liveUsername)localStorage.setItem('qa-live-phone:'+liveUsername,$('live-phone').value.trim());}catch{}};$('live-refresh').onclick=loadLive;$('live-interval').onchange=scheduleLive;

async function readLiveResponse(response){if(!(response.headers.get('Content-Type')||'').includes('application/json'))throw Error('The live service returned HTTP '+response.status+'. Please try again shortly.');return response.json();}
